package com.example.payment.integrationtest.paymentgateway;

import static com.github.tomakehurst.wiremock.client.WireMock.aResponse;
import static com.github.tomakehurst.wiremock.client.WireMock.equalTo;
import static com.github.tomakehurst.wiremock.client.WireMock.equalToJson;
import static com.github.tomakehurst.wiremock.client.WireMock.post;
import static com.github.tomakehurst.wiremock.client.WireMock.postRequestedFor;
import static com.github.tomakehurst.wiremock.client.WireMock.urlEqualTo;
import static com.github.tomakehurst.wiremock.client.WireMock.verify;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.github.tomakehurst.wiremock.junit5.WireMockExtension;
import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import java.math.BigDecimal;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.RegisterExtension;
import org.springframework.web.client.RestClient;

/**
 * Verifies the contract between {@link HttpPaymentGateway} and the payment provider's
 * REST API: the request we send, and every shape of answer we must be able to read back,
 * including the provider refusing the payment outright.
 */
class HttpPaymentGatewayTest {

    @RegisterExtension
    static WireMockExtension provider = WireMockExtension.newInstance().options(com.github.tomakehurst.wiremock.core.WireMockConfiguration.wireMockConfig().dynamicPort()).build();

    private HttpPaymentGateway gateway;

    @BeforeEach
    void setUp() {
        var client = RestClient.builder().baseUrl(provider.baseUrl()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @Test
    void sends_the_reference_and_amount_the_provider_expects() {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        gateway.authorize("ORD-1", new Money(new BigDecimal("12.50"), "eur"));

        provider.verify(postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withHeader("Content-Type", equalTo("application/json"))
                .withRequestBody(equalToJson("{\"reference\":\"ORD-1\",\"amount\":12.50,\"currency\":\"EUR\"}")));
    }

    @Test
    void reads_back_an_approved_decision() {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        var outcome = gateway.authorize("ORD-2", new Money(new BigDecimal("10"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void reads_back_a_declined_decision() {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"declined\"}")));

        var outcome = gateway.authorize("ORD-3", new Money(new BigDecimal("10"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void treats_a_payment_the_provider_refuses_outright_as_declined() {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(402).withHeader("Content-Type", "application/json")
                        .withBody("{\"error\":\"insufficient_funds\"}")));

        var outcome = gateway.authorize("ORD-4", new Money(new BigDecimal("10"), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void surfaces_an_unexpected_provider_error_as_a_failure() {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(500)));

        assertThatThrownBy(() -> gateway.authorize("ORD-5", new Money(new BigDecimal("10"), "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
}

